import com.project.system.service.*;import java.util.*;import org.springframework.context.annotation.AnnotationConfigApplicationContext;
public class MerchantExtraIntegration{static int n;static void check(boolean b,String name){if(!b)throw new AssertionError(name);n++;System.out.println("PASS "+name);}static void reject(Runnable r,String name){try{r.run();}catch(IllegalArgumentException e){check(true,name);return;}throw new AssertionError(name);}public static void main(String[]args)throws Exception{try(AnnotationConfigApplicationContext c=new AnnotationConfigApplicationContext(MerchantIntegration.Config.class)){MerchantService s=c.getBean(MerchantService.class);String type=s.addCategory("扩展测试"+System.nanoTime(),1);check(s.categories().stream().anyMatch(x->type.equals(x.get("code"))),"dynamic category added");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_RGB),"png",out);String img=s.image(out.toByteArray(),1);check("image/png".equals(s.image(img).get("mime")),"image upload decode and retrieval");Map<String,String>x=new HashMap<>();x.put("owner_name","负责人测试");x.put("owner_phone","13800000002");x.put("license_no","LICENSE-TEST");x.put("permit_no","PERMIT-TEST");x.put("permit_expiry","2027-12-31");x.put("introduction","简介测试");x.put("license_image",img);x.put("permit_image",img);x.put("merchant_image",img);long id=s.saveFull(null,"扩展商户",type,"联系人","13800000002","测试地址","",1,x);check("负责人测试".equals(s.info(id).get("owner_name")),"owner saved");check("LICENSE-TEST".equals(s.info(id).get("license_no")),"license saved");check(img.equals(s.info(id).get("merchant_image")),"merchant photo linked");check(((Number)s.search(null,null,null,null,1,"负责人测试","2020-01-01","2030-01-01").get("total")).longValue()>0,"owner and creation date search");check(((Number)s.search(null,null,null,null,1,"负责人测试","2000-01-01","2000-01-02").get("total")).longValue()==0,"creation date excludes other times");reject(()->s.image(new byte[]{1,2,3},1),"invalid image rejected");reject(()->s.image(new byte[3*1024*1024+1],1),"oversized image rejected");x.put("owner_name","");reject(()->s.saveFull(null,"无负责人",type,"x","123456","x","",1,x),"missing owner rejected");System.out.println("PASS TOTAL "+n);}}}
